 inv=[]
 for a in m['assets']:
  for l in a['lods']:
   d,b=C.read_glb(HERE/l['file']);inv.append({'file':l['file'],'sha256':l['sha256'],'materials':d['materials'],'textures':d.get('textures',[]),'images':l['images'],'lights':len(d.get('extensions',{}).get('KHR_lights_punctual',{}).get('lights',[])),'primitiveCount':l['primitives']})
